var n=`0129-khachapuri-imeruli`;var a=`world-0129`;var t=`GE`;var o=`western-asia`;var r=4;var l=103;var s={en:`Khachapuri Imeruli`,ua:`Хачапурі по-імеретинськи`};var u={en:`Imeretian round cheese-filled bread, using a blend of available cheeses in place of traditional Imeretian cheese.`,ua:`Імеретинський круглий хліб із сирною начинкою, для якої використано суміш доступних сирів замість традиційного імеретинського.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 60 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 60 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:60,i:[[`all-purpose-flour`,500,`g`],[`water`,280,`ml`],[`instant-yeast`,7,`g`],[`table-salt`,6,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`mozzarella`,350,`g`],[`farmer-cheese`,250,`g`],[`unsalted-butter`,40,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 20 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 20 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:20,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 15 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 15 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`chicken-egg`,1,`pcs`]]}];var h={slug:n,id:a,country:`GE`,region:o,servings:4,minutes:103,title:s,text:u,steps:g};export{t as country,h as default,a as id,l as minutes,o as region,r as servings,n as slug,g as steps,u as text,s as title};